<?php $title='Workflow Builder';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1><?=e($service['name']??'Service')?> Workflow Builder</h1><p>Configure the steps executed for each client project.</p></div></div><div class="grid two"><div class="panel"><h2><?=e($version['name']??'Workflow')?></h2><?php foreach($steps as $st):?><div class="step"><strong><?=e($st['sort_order'])?>. <?=e($st['title'])?></strong><span class="badge"><?=e($st['requirement'])?></span><small><?=e($st['step_type'])?></small></div><?php endforeach;?></div><form class="panel form-grid" method="post" action="<?=route('service.workflow',['id'=>$service['id']])?>/steps"><?=csrf_field()?><label>Title<input name="title" required></label><label>Type<select name="step_type"><option>checkbox</option><option>client_information</option><option>document_upload</option><option>website_link</option><option>comment</option><option>invoice</option><option>quotation</option><option>payment</option><option>secure_area</option><option>approval</option><option>preparation</option><option>submission</option><option>completion</option></select></label><label>Requirement<select name="requirement"><option>required</option><option>optional</option><option>conditional</option></select></label><label>Sort order<input name="sort_order" type="number" value="50"></label><label class="wide">Configuration JSON<textarea name="config_json" placeholder='{"show_initials":true}'></textarea></label><div class="wide"><button class="primary">Add workflow step</button></div></form></div><?php require __DIR__.'/../layouts/footer.php';?>
